(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)');const button=document.querySelector('#motion');let disabled=reduce.matches;const letters=[...document.querySelectorAll('.builder>span')];const system=document.querySelector('.system-visual');const progress=document.querySelector('.progress');let pending=false;const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));function paint(){pending=false;const y=scrollY,h=innerHeight;progress.style.transform=`scaleX(${clamp(y/(document.documentElement.scrollHeight-h))})`;if(disabled)return;letters.forEach((l,i)=>{const p=clamp(y/h);l.style.transform=`translateY(${p*(i%2?-32:25)}px) rotate(${p*(i-3)*1.5}deg)`});if(system){const sr=system.getBoundingClientRect();system.style.transform=`rotate(${clamp((sr.top/h)*6,-3,3)}deg)`}}function request(){if(!pending){pending=true;requestAnimationFrame(paint)}}function sync(){document.body.classList.toggle('no-motion',disabled);button.setAttribute('aria-pressed',String(disabled));button.textContent=disabled?'Motion off':'Motion on';document.documentElement.style.scrollBehavior=disabled?'auto':'smooth';request()}button.addEventListener('click',()=>{disabled=!disabled;sync()});reduce.addEventListener('change',e=>{disabled=e.matches;sync()});addEventListener('scroll',request,{passive:true});addEventListener('resize',request);sync()})();
